; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: system80 (Dick Smith System 80 / Video Genie (direct video)), starts in normal mode
; ============================================================

			org #5200

; ============================================================
; Platform start code (the platform's ntc_plat_romhead) - at the org, on to ntc_start
; ============================================================
; Entry at ;@org (the /CMD transfer address). Model I / System 80: di is enough -
; there is no E4/E0 to clear (the disk IRQ is maskable, via #37E0).  ;!!S80
ntc_s80_start:
			di
			jp ntc_start

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_trs_stack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 2: Randomize 1234
			dw kw_seedl, 1234

			; 3: again:
lbl_again:

			; 4: t = Rnd(100) + 1 : tries = 0
			dw kw_rndl, 100, tmp0
			dw kw_addl, tmp0, 1, var_t
			dw kw_ztov, var_tries

			; 5: Print "I picked 1 to 100"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 6: Do
do1_t:

			; 7: Input "Guess"; g
			dw kw_printstrvar, str1
			dw kw_inputint_n, var_g

			; 8: tries = tries + 1
			dw kw_inc, var_tries

			; 9: If g < t Then
			dw kw_scpltvv, var_g, var_t
			dw kw_goto_iffalse_n, if2_1

			; 10: Print "Higher"
			dw kw_printstrvar, str2
			dw kw_printnl

			; 11: ElseIf g > t Then
			dw if2_e_go
if2_1:
			dw kw_scpgtvv, var_g, var_t
			dw kw_goto_iffalse_n, if2_2

			; 12: Print "Lower"
			dw kw_printstrvar, str3
			dw kw_printnl

			; 13: End If
if2_2:
if2_e:

			; 14: Loop Until g = t
			dw kw_cpeqvv, var_g, var_t
			dw kw_goto_iffalse_n, do1_t
do1_e:

			; 15: Print "Got it in "; tries
			dw kw_printstrvar, str4
			dw kw_printint, var_tries
			dw kw_printnl

			; 16: Input "Again (y/n)"; a$
			dw kw_printstrvar, str5
			dw kw_inputstr_n, var_a

			; 17: If a$ = "y" Then GoTo again
			dw kw_strcmpeq, var_a, str6
			dw kw_goto_iftrue_n, lbl_again

			; 18: End
			dw kw_printnl0
			dw kw_printstrvar, str7
			dw kw_waitkey_n
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if2_e_go:			ld sp, if2_e
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_t:			dw 0
var_tries:			dw 0
var_g:			dw 0
			db 40			; capacity
var_a:			ds 41
tmp0:			dw 0

; ============================================================
; Strings
; ============================================================

str0:			db "I picked 1 to 100", 0
str1:			db "Guess? ", 0
str2:			db "Higher", 0
str3:			db "Lower", 0
str4:			db "Got it in ", 0
str5:			db "Again (y/n)? ", 0
str6:			db "y", 0
str7:			db "Press a key", 0

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared ntc_d_nmode
; ------------------------------------------------------------
; Scratch space: the core every program has (with ntc_d_nmode). The rest of
; the run time's variables are @data sections, each linked only when a
; linked section's code names one of its labels (no header lists them).
; They stay in this order: the keyword ROM's registry keeps each variable's
; address (a Library: ROM program has them as fixed addresses)
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread

;## ntc_d_nmode @data
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)

;## ntc_d_div @data
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)

;## ntc_d_lead @data
ntc_lead:		db 0			; printint: digit seen

;## ntc_d_icnt @data
ntc_icnt:		db 0			; gets: chars typed
ntc_icap:		db 0			; gets: the buffer's capacity

;## ntc_d_sptr @data
ntc_sptr:		dw 0			; printbuf: text pointer

;## ntc_d_iptr @data
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done

;## ntc_d_ivar @data
ntc_ivar:		dw 0			; inputint / inkey: dest var

;## ntc_d_aptr @data
ntc_aptr:		dw 0			; atoi: text pointer

;## ntc_d_numbuf @data
ntc_numbuf:		ds 14			; printint / long print: digits (+ spaces for Option VBPrint)

;## ntc_d_inbuf @data
				db 40			; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:		ds 41			; inputint: typed text

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## kw_waitkey (normal mode copy) ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey_n:
			ld ix, ntc_xn
			jp ntc_plat_getkey_n

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_goto_iftrue (normal mode copy)
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue_n:
			pop hl
			jp nz, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			add hl, de
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_div ntc_data
; HL / DE signed, truncating. (ntc_mode) 0 = quotient, 1 = remainder.
; Remainder takes the dividend's sign. Divide by zero gives
; quotient 0, remainder = dividend. Pops destvar and stores.
ntc_div:
			ld a, d
			or e
			jr nz, ntc_div_nz
			ld a, (ntc_mode)
			or a
			jr nz, ntc_div_store
			ld hl, 0
			jr ntc_div_store
ntc_div_nz:
			ld a, h
			ld (ntc_sgnr), a
			xor d
			ld (ntc_sgnq), a
			bit 7, h
			jr z, ntc_div_hpos
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_hpos:
			bit 7, d
			jr z, ntc_div_dpos
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_div_dpos:
			ld a, h
			ld c, l
			ld hl, 0
			ld b, 16
ntc_div_loop:
			sla c
			rla
			adc hl, hl
			sbc hl, de
			jr nc, ntc_div_one
			add hl, de
			djnz ntc_div_loop
			jr ntc_div_done
ntc_div_one:
			inc c
			djnz ntc_div_loop
ntc_div_done:
			ld b, a
			ld a, (ntc_mode)
			or a
			jr z, ntc_div_q
			ld a, (ntc_sgnr)
			jr ntc_div_sign
ntc_div_q:
			ld h, b
			ld l, c
			ld a, (ntc_sgnq)
ntc_div_sign:
			rla
			jr nc, ntc_div_store
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_div_store:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvv ntc_cmp
;kw_scpltvv, <var1>, <var2>  - signed var1 < var2
kw_scpltvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_slt

;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_sgt

;## kw_cpeqvv ntc_cmp
;kw_cpeqvv, <var1>, <var2>
kw_cpeqvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_eq

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			pop de
ntc_rnd:
			ld hl, (ntc_rnd_seed)
			ld a, h
			rra
			ld a, l
			rra
			xor h
			ld h, a
			ld a, l
			rra
			ld a, h
			rra
			xor l
			ld l, a
			xor h
			ld h, a
			ld (ntc_rnd_seed), hl
			bit 7, d
			jr nz, ntc_rnd_zero
			ld a, d
			or e
			jr z, ntc_rnd_zero
			ld a, 1
			ld (ntc_mode), a
			res 7, h
			jp ntc_div
ntc_rnd_zero:
			ld hl, 0
			jp ntc_div_store

;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			pop hl
ntc_seed:
			ld a, h
			or l
			jr nz, ntc_seed_ok
			inc l
ntc_seed_ok:
			ld (ntc_rnd_seed), hl
			ret

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; Functions that build a string write into a temp, so they cut at
; NTC_STRMAX (the longest string in the program, set by the compiler);
; kw_strcpy / kw_strcat / input cut at the destination's capacity.
; ============================================================

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			ld a, (ntc_curx)
			or a
			ret z
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## ntc_gets (normal mode copy) ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and DEL (or backspace). HL = buffer (its capacity in the byte
; before it), DE = where to
; jp when done (after the newline). 40 chars max, 0 terminated.
ntc_gets_n:
			ld (ntc_iptr), hl
			ld (ntc_ilink), de
			dec hl
			ld a, (hl)			; the buffer's capacity
			ld (ntc_icap), a
			xor a
			ld (ntc_icnt), a
ntc_gs_wait_n:
			ld ix, ntc_gs_key_n
			jp ntc_plat_getkey_n
ntc_gs_key_n:
			cp 13
			jr z, ntc_gs_done_n
			cp 127
			jr z, ntc_gs_del_n
			cp 8
			jr z, ntc_gs_del_n
			cp 32
			jr c, ntc_gs_wait_n
			ld c, a
			ld a, (ntc_icap)
			ld b, a
			ld a, (ntc_icnt)
			cp b
			jr nc, ntc_gs_wait_n
			inc a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			ld (hl), c
			inc hl
			ld (ntc_iptr), hl
			ld a, c
			ld ix, ntc_gs_wait_n
			jp ntc_plat_putc
ntc_gs_del_n:
			ld a, (ntc_icnt)
			or a
			jr z, ntc_gs_wait_n
			dec a
			ld (ntc_icnt), a
			ld hl, (ntc_iptr)
			dec hl
			ld (ntc_iptr), hl
			ld ix, ntc_gs_wait_n
			jp ntc_plat_backspace
ntc_gs_done_n:
			ld hl, (ntc_iptr)
			ld (hl), 0
			ld ix, (ntc_ilink)
			jp ntc_plat_newline

;## kw_inputstr (normal mode copy) ntc_gets
;kw_inputstr, <straddr>
kw_inputstr_n:
			pop hl
			ld de, ntc_xn
			jp ntc_gets_n

;## kw_inputint (normal mode copy) ntc_gets ntc_atoi
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint_n:
			pop hl
			ld (ntc_ivar), hl
			ld hl, ntc_inbuf
			ld de, ntc_atoi
			jp ntc_gets_n

;## ntc_atoi ntc_data
; text to number into the var at (ntc_ivar). ntc_atoi reads ntc_inbuf,
; ntc_atoi_hl reads HL. Spaces first, then - , then digits (or &H hex).
ntc_atoi:
			ld hl, ntc_inbuf
ntc_atoi_hl:
			ld a, (hl)
			cp ' '
			jr nz, ntc_atoi_sign
			inc hl
			jr ntc_atoi_hl
ntc_atoi_sign:
			ld c, 0
			cp '-'
			jr nz, ntc_atoi_amp
			inc c
			inc hl
			ld a, (hl)
ntc_atoi_amp:
			ld de, 0
			cp '&'
			jr nz, ntc_atoi_loop
			inc hl
			ld a, (hl)
			or #20
			cp 'h'
			jr nz, ntc_atoi_done
			inc hl
ntc_atoi_hex:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr c, ntc_atoi_hd
			or #20
			sub 'a' - '0'
			jr c, ntc_atoi_done
			cp 6
			jr nc, ntc_atoi_done
			add a, 10
ntc_atoi_hd:
			ex de, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			or l
			ld l, a
			ex de, hl
			inc hl
			jr ntc_atoi_hex
ntc_atoi_loop:
			ld a, (hl)
			sub '0'
			jr c, ntc_atoi_done
			cp 10
			jr nc, ntc_atoi_done
			ld (ntc_aptr), hl
			ex de, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de
			add hl, hl
			ld e, a
			ld d, 0
			add hl, de
			ex de, hl
			ld hl, (ntc_aptr)
			inc hl
			jr ntc_atoi_loop
ntc_atoi_done:
			ld a, c
			or a
			jr z, ntc_atoi_store
			xor a
			sub e
			ld e, a
			sbc a, a
			sub d
			ld d, a
ntc_atoi_store:
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_plat_data ntc_data
VIDEO       equ #3C00               ; video RAM base
VIDCOLS     equ 64
VIDROWS     equ 16
VIDLAST     equ VIDEO + VIDCOLS*(VIDROWS-1)   ; #3FC0, start of the bottom row
INTMASK     equ #E0                 ; maskable interrupt mask (write) / status (read)
INTCLR      equ #EC                 ; read clears the 30Hz clock interrupt
NMIMASK     equ #E4                 ; NMI mask: bit7 INTRQ, bit6 DRQ; 0 = off  ;!!TRS
DOSRET      equ #402D               ; DOS return entry (TRSDOS 1.3 III; TRSDOS 2.3 / NEWDOS I) ;!!TRS

ntc_curx:   db 0                    ; column (0..63), counted for Tab
ntc_cury:   db 0                    ; row (0..15)
ntc_scols:  db 64
ntc_frames: dw 0                    ; frames counted by ntc_plat_frame (ntc_plat_ticks)
ntc_trs_stack equ ntc_end + 256     ; the real stack: the 256 bytes above the program image

;## ntc_plat_screen ntc_plat_data ntc_data
; routines here are entered via jp with IX = where to go next; they end jp (ix).
; No real stack: direct memory writes only, so no call / no push on the thread.

; ntc_plat_putc - A = character; write it at the cursor, advance (wrap -> newline)
ntc_plat_putc:
			ld c, a                     ; keep the char
			; HL = VIDEO + cury*64 + curx  (inline, no call)
			ld a, (ntc_cury)
			ld h, 0
			ld l, a
			add hl, hl                  ; *2
			add hl, hl                  ; *4
			add hl, hl                  ; *8
			add hl, hl                  ; *16
			add hl, hl                  ; *32
			add hl, hl                  ; *64
			ld a, (ntc_curx)
			ld e, a
			ld d, 0
			add hl, de
			ld de, VIDEO
			add hl, de
			ld (hl), c                  ; draw the character
			ld a, (ntc_curx)
			inc a
			cp VIDCOLS
			jr c, ntc_pc_col
			jp ntc_plat_newline         ; past column 63 -> newline
ntc_pc_col:
			ld (ntc_curx), a
			jp (ix)

; ntc_plat_newline - column 0, next row; scroll when past the bottom row
ntc_plat_newline:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp VIDROWS
			jr c, ntc_nl_row
			; scroll rows 1..15 up to 0..14, blank the bottom row (ldir, no push)
			ld hl, VIDEO + VIDCOLS
			ld de, VIDEO
			ld bc, VIDCOLS*(VIDROWS-1)  ; 960
			ldir
			ld hl, VIDLAST
			ld (hl), ' '
			ld de, VIDLAST + 1
			ld bc, VIDCOLS - 1
			ldir
			ld a, VIDROWS-1
ntc_nl_row:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_backspace - back up a column and blank it
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr z, ntc_bs_done
			dec a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			ld h, 0
			ld l, a
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl                  ; *64
			ld a, (ntc_curx)
			ld e, a
			ld d, 0
			add hl, de
			ld de, VIDEO
			add hl, de
			ld (hl), ' '
ntc_bs_done:
			jp (ix)

;## ntc_plat_key (normal mode copy) ntc_plat_data ntc_data
; ntc_plat_scankey - A = ASCII of a held key, 0 if none.  ntc_plat_getkey - wait.
; Both swap SP to the real stack so the one scan body (ntc_trs_scan, call/ret)
; can be called safely, then swap back. ntc_trs_scan reads the matrix rows
; directly (#3800+2^row). Core subset: A-Z, 0-9, ENTER (13), SPACE (32).
; ;!!TRS SHIFT (#3880 bit0/bit1), the symbol keys (#3820 bits 2-7) and the CPC-
; style key numbers the Keys class wants are not mapped yet.
ntc_plat_scankey_n:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			call ntc_trs_scan_n
			ld sp, (ntc_ip)
			jp (ix)
ntc_plat_getkey_n:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
ntc_gk_wait_n:
			call ntc_trs_scan_n
			or a
			jr z, ntc_gk_wait_n
			ld sp, (ntc_ip)
			jp (ix)

; ntc_trs_scan - A = ASCII of a held key, 0 if none (call/ret, real stack)
ntc_trs_scan_n:
			ld hl, ntc_trs_ktab_n
ntc_sc_row_n:
			ld e, (hl)
			inc hl
			ld d, (hl)                  ; DE = row address (0 ends the table)
			inc hl
			ld a, d
			or e
			jr z, ntc_sc_r6_n             ; table end -> ENTER / SPACE row
			ld c, (hl)                  ; C = base char (bit 0)
			inc hl
			ld b, (hl)                  ; B = allowed-bit mask
			inc hl
			ld a, (de)
			and b
			jr z, ntc_sc_row_n            ; nothing held in this row
			ld b, c                     ; B = base char; find the lowest set bit
ntc_sc_bit_n:
			rra
			jr c, ntc_sc_hit_n
			inc b
			jr ntc_sc_bit_n
ntc_sc_hit_n:
			ld a, b
			jp ntc_xn
ntc_sc_r6_n:
			ld a, (#3840)               ; ENTER CLEAR BREAK arrows SPACE
			bit 0, a
			jr z, ntc_sc_sp_n
			ld a, 13                    ; ENTER
			jp ntc_xn
ntc_sc_sp_n:
			ld a, (#3840)
			bit 7, a
			jr z, ntc_sc_none_n
			ld a, 32                    ; SPACE
			jp ntc_xn
ntc_sc_none_n:
			xor a
			jp ntc_xn

; row-address / base-char / allowed-mask table (bit 0 = base char, bit n = base+n)
ntc_trs_ktab_n:
			dw #3801
			db '@', #FF                 ; @ A B C D E F G
			dw #3802
			db 'H', #FF                 ; H I J K L M N O
			dw #3804
			db 'P', #FF                 ; P Q R S T U V W
			dw #3808
			db 'X', #07                 ; X Y Z
			dw #3810
			db '0', #FF                 ; 0 1 2 3 4 5 6 7
			dw #3820
			db '8', #03                 ; 8 9 (bits 2-7 are : ; , - . /  ;!!TRS)
			dw 0

;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - End: hand back to the DOS at its return entry (#402D).
ntc_plat_exit:
			jp DOSRET


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
